CREATE TABLE IF NOT EXISTS intelligence_consensus (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), assessment_id uuid NOT NULL REFERENCES intelligence_assessments(id) ON DELETE CASCADE, consensus_type text NOT NULL, consensus_value numeric(20,6), confidence numeric(6,2), source_count integer NOT NULL DEFAULT 0, verified_source_count integer NOT NULL DEFAULT 0, conflict_count integer NOT NULL DEFAULT 0, rationale text, created_at timestamptz NOT NULL DEFAULT now());